// devices.device.register — generated by `pnpm gen:command`. Keep the guard cases; add the acceptance criterion as
// its own case before you change the handler (04-testing §1).
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, countRows, createTestDatabase, type TestDatabase } from '@ocs/testing';
import { Forbidden, openTestKernel, ValidationFailed, type TestKernel } from '../../kernel/index.ts';
import { registerDevice } from '../commands/register-device.ts';

const allowed = aStaffActor();
const other = aStaffActor();
const audited = async () => countRows(testDb.url, 'audit_event WHERE command = $1', [registerDevice.name]);
let testDb: TestDatabase;
let t: TestKernel;

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url);
  t.grant(allowed, registerDevice.permission);
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('devices.device.register', () => {
  it('refuses an actor without the permission and records nothing', async () => {
    await expect(
      t.kernel.execute(registerDevice, other, { id: randomUUID() }, 'test'),
    ).rejects.toBeInstanceOf(Forbidden);
    expect(await audited()).toBe(0);
  });

  it('refuses invalid input', async () => {
    await expect(
      t.kernel.execute(registerDevice, allowed, { id: 'not-a-uuid' }, 'test'),
    ).rejects.toBeInstanceOf(ValidationFailed);
  });

  it('records exactly one audit event', async () => {
    await t.kernel.execute(registerDevice, allowed, { id: randomUUID() }, 'test');
    expect(await audited()).toBe(1);
  });
});
